#include <nuttx/config.h>

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define WAV_RATE      8000  /* sample rate (Hz)   */
#define WAV_SECS      1     /* duration (seconds) */
#define WAV_CHANNELS  1     /* mono               */
#define WAV_BPS       16    /* bits per sample    */

#define WAV_PATH      "/data/hello.wav"
#define PLAY_CMD      "nxplayer " WAV_PATH

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static void put_le16(FAR uint8_t *p, uint16_t v)
{
  p[0] = (uint8_t)(v & 0xff);
  p[1] = (uint8_t)((v >> 8) & 0xff);
}

static void put_le32(FAR uint8_t *p, uint32_t v)
{
  p[0] = (uint8_t)(v & 0xff);
  p[1] = (uint8_t)((v >> 8) & 0xff);
  p[2] = (uint8_t)((v >> 16) & 0xff);
  p[3] = (uint8_t)((v >> 24) & 0xff);
}

/* Write a real, valid 16-bit PCM WAV file (mono, 8 kHz, 1 s).
 *
 * Layout: 44-byte RIFF/WAVE header + raw PCM samples.
 *   RIFF chunk : "RIFF" + (36 + dataSize) + "WAVE"
 *   fmt  chunk : PCM(1) / channels / sampleRate / byteRate / blockAlign /
 *                bitsPerSample
 *   data chunk : "data" + dataSize
 *
 * Returns 0 on success, -1 on failure.
 */

static int gen_wav(FAR const char *path)
{
  FILE *fp;
  uint8_t hdr[44];
  uint8_t sample[2];
  uint16_t val;
  int i;
  int nsamples = WAV_RATE * WAV_SECS;
  uint32_t datasize = (uint32_t)nsamples * (WAV_BPS / 8);
  uint32_t byterate = WAV_RATE * WAV_CHANNELS * (WAV_BPS / 8);
  uint16_t blockalign = WAV_CHANNELS * (WAV_BPS / 8);

  memset(hdr, 0, sizeof(hdr));

  /* RIFF header */

  memcpy(hdr + 0,  "RIFF", 4);
  put_le32(hdr + 4, 36 + datasize);
  memcpy(hdr + 8,  "WAVE", 4);

  /* fmt chunk */

  memcpy(hdr + 12, "fmt ", 4);
  put_le32(hdr + 16, 16);                  /* fmt chunk size       */
  put_le16(hdr + 20, 1);                   /* PCM format           */
  put_le16(hdr + 22, WAV_CHANNELS);        /* mono                 */
  put_le32(hdr + 24, WAV_RATE);            /* sample rate          */
  put_le32(hdr + 28, byterate);            /* byte rate            */
  put_le16(hdr + 32, blockalign);          /* block align          */
  put_le16(hdr + 34, WAV_BPS);             /* bits per sample      */

  /* data chunk */

  memcpy(hdr + 36, "data", 4);
  put_le32(hdr + 40, datasize);

  fp = fopen(path, "wb");
  if (fp == NULL)
    {
      printf("ai_glasses: ERROR: cannot create %s\n", path);
      return -1;
    }

  if (fwrite(hdr, 1, sizeof(hdr), fp) != sizeof(hdr))
    {
      printf("ai_glasses: ERROR: failed to write WAV header\n");
      fclose(fp);
      return -1;
    }

  /* Sawtooth waveform samples (no libm dependency) */

  for (i = 0; i < nsamples; i++)
    {
      val = (uint16_t)((i * 8) & 0xffff);
      sample[0] = (uint8_t)(val & 0xff);
      sample[1] = (uint8_t)((val >> 8) & 0xff);
      fwrite(sample, 1, 2, fp);
    }

  fclose(fp);
  printf("ai_glasses: WAV generated: %s (%u bytes)\n", path,
         datasize + (uint32_t)sizeof(hdr));
  return 0;
}

/* Play the generated WAV file through the registered audio device using
 * the nxplayer command line player.
 */

static int play_wav(void)
{
  int ret;

  printf("ai_glasses: play via: %s\n", PLAY_CMD);
  ret = system(PLAY_CMD);
  printf("ai_glasses: nxplayer returned %d\n", ret);
  return ret;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * ai_glasses_main
 ****************************************************************************/

int main(int argc, FAR char *argv[])
{
  int ret;

  printf("Hello, AI Glasses World!!\n");

  ret = gen_wav(WAV_PATH);
  if (ret < 0)
    {
      printf("ai_glasses: FAILED to generate WAV (%d)\n", ret);
      return ret;
    }

  ret = play_wav();
  if (ret == 0)
    {
      printf("ai_glasses: voice playback SUCCESS\n");
    }
  else
    {
      printf("ai_glasses: voice playback FAILED (%d)\n", ret);
    }

  return 0;
}

